// coverage_test.go: the Go twin of webv2.coverage pinned to oracles
// generated by .scratch/t10/gen-vectors.py against the live Python module.
// Every expectation in testdata/ was produced by the Python twin; nothing
// here is hand-written.
//
// The structural-index seam is process-global, so these tests are strictly
// sequential (no t.Parallel) and each one that installs a seam restores the
// absent-module default via t.Cleanup.
package coverage

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"websec/internal/state"
	"websec/internal/validation"
)

// pinnedNow is the clock both twins pin (WEBV2_NOW).
const pinnedNow = "2026-02-01T00:00:00.000000+00:00"

// readTest loads one testdata artifact as an ordered Value.
func readTest(t *testing.T, name string) validation.Value {
	t.Helper()
	v, err := validation.ReadJson(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read testdata/%s: %v", name, err)
	}
	return v
}

// casesOf is doc.cases.
func casesOf(t *testing.T, doc validation.Value) []validation.Value {
	t.Helper()
	cases := objAt(doc, "cases")
	if cases.Kind != validation.Arr {
		t.Fatalf("cases: not an array")
	}
	return cases.A
}

// parseCanon turns a stored canon string back into an ordered Value.
func parseCanon(t *testing.T, label, canon string) validation.Value {
	t.Helper()
	v, err := validation.ParseOrdered([]byte(canon))
	if err != nil {
		t.Fatalf("%s: parse canon: %v", label, err)
	}
	return v
}

// wantCanon compares one Value against a Python-generated canon string.
func wantCanon(t *testing.T, label string, got validation.Value, want string) {
	t.Helper()
	if got := validation.CanonCompact(got); got != want {
		t.Errorf("%s:\n got  %s\n want %s", label, got, want)
	}
}

// wantError pins the Python error text: str(exception), which is what the
// CLI prints (KeyError renders as the repr of its message).
func wantError(t *testing.T, label string, err error, c validation.Value) {
	t.Helper()
	ec := objAt(c, "error")
	if err == nil {
		t.Fatalf("%s: expected %s, got nil", label, objStr(ec, "type"))
	}
	if want := objStr(ec, "str"); err.Error() != want {
		t.Errorf("%s: error = %q, want %q", label, err.Error(), want)
	}
}

// readFile reads a file or fails the test.
func readFile(t *testing.T, path string) string {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	return string(raw)
}

// wantFile compares the on-disk ledger byte-for-byte with the Python oracle.
func wantFile(t *testing.T, label, path, want string) {
	t.Helper()
	if got := readFile(t, path); got != want {
		t.Errorf("%s: ledger text mismatch\n got  %q\n want %q", label, got, want)
	}
}

// newCamp creates a campaign with the oracle's campaign id and the pinned
// clock the generator used.
func newCamp(t *testing.T, cid string) *state.Campaign {
	t.Helper()
	c, err := state.Init(t.TempDir(), "Acme Program", state.InitOpts{CampaignID: cid})
	if err != nil {
		t.Fatalf("state.Init(%s): %v", cid, err)
	}
	return c
}

// seedCampaign recreates the oracle's campaign from a stored seed document:
// the campaign id and the ledger bytes come from the oracle itself.
func seedCampaign(t *testing.T, label, seed string) *state.Campaign {
	t.Helper()
	doc := parseCanon(t, label, seed)
	cid := objStr(doc, "campaign_id")
	if cid == "" {
		t.Fatalf("%s: seed has no campaign_id", label)
	}
	c := newCamp(t, cid)
	// The seed is the exact ledger text the generator's campaign held.
	if err := os.WriteFile(Path(c), []byte(seed), 0o644); err != nil {
		t.Fatalf("%s: write seed: %v", label, err)
	}
	return c
}

// writeFindings writes one F-*.json per finding, as the generator did.
func writeFindings(t *testing.T, c *state.Campaign, findings []validation.Value) {
	t.Helper()
	for _, f := range findings {
		p := filepath.Join(c.FindingsDir, objStr(f, "finding_id")+".json")
		if err := validation.WriteJson(p, f, ""); err != nil {
			t.Fatal(err)
		}
	}
}

// setActiveSnapshot rewrites campaign_state.json with the pinned snapshot,
// mirroring the generator's write_state.
func setActiveSnapshot(t *testing.T, c *state.Campaign, sid validation.Value) {
	t.Helper()
	st, err := validation.ReadJson(c.StatePath)
	if err != nil {
		t.Fatal(err)
	}
	st.O = validation.SetOrAppend(st.O, "active_snapshot_id", sid)
	if pyTruthy(sid) {
		st.O = validation.SetOrAppend(st.O, "snapshots", validation.VArr(validation.VObj(
			kv("snapshot_id", sid),
			kv("pinned_at", validation.VStr(nowIso())),
			kv("status", validation.VStr("pinned")),
		)))
	}
	if err := validation.WriteJson(c.StatePath, st, "campaign_state"); err != nil {
		t.Fatal(err)
	}
}

// writeSnapshot stores the snapshot document the generator used.
func writeSnapshot(t *testing.T, c *state.Campaign, sid, body string) {
	t.Helper()
	dir := filepath.Join(c.Dir, "snapshots", sid)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "snapshot.json"), []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
}

// fakeExternalSurface is the test-local structural_index replica used to wire
// the seam (verified against the real Python module below).
func fakeExternalSurface(index validation.Value) []validation.Value {
	out := []validation.Value{}
	for _, n := range listField(index, "nodes") {
		if objStr(n, "kind") == "function" && pyTruthy(objAt(n, "is_entry_point")) {
			out = append(out, n)
		}
	}
	return out
}

// fakeExternalCallSites is external_call_sites: calls_external or delegatecalls.
func fakeExternalCallSites(index validation.Value) []validation.Value {
	out := []validation.Value{}
	for _, n := range listField(index, "nodes") {
		if objStr(n, "kind") != "function" {
			continue
		}
		if pyTruthy(objAt(n, "calls_external")) || pyTruthy(objAt(n, "delegatecalls")) {
			out = append(out, n)
		}
	}
	return out
}

// installFakeIndex wires the seam for one test and restores the absent-module
// default afterwards.
func installFakeIndex(t *testing.T) {
	t.Helper()
	SetStructuralIndex(StructuralIndexAPI{
		ExternalSurface:   fakeExternalSurface,
		ExternalCallSites: fakeExternalCallSites,
	})
	t.Cleanup(func() { SetStructuralIndex(StructuralIndexAPI{}) })
}

// idsOf projects node ids for comparison with the structural oracle.
func idsOf(nodes []validation.Value) validation.Value {
	out := make([]validation.Value, len(nodes))
	for i, n := range nodes {
		out[i] = validation.VStr(objStr(n, "id"))
	}
	return validation.VArr(out...)
}

// TestStructuralIndexSeam pins the seam default and the test replica against
// the real Python structural_index oracle.
func TestStructuralIndexSeam(t *testing.T) {
	doc := readTest(t, "structural_index.json")
	index := objAt(doc, "index")
	oracle := objAt(doc, "oracle")

	SetStructuralIndex(StructuralIndexAPI{})
	if got := siAPI.ExternalSurface(index); len(got) != 0 {
		t.Errorf("absent-module surface = %d nodes, want 0", len(got))
	}
	if got := siAPI.ExternalCallSites(index); len(got) != 0 {
		t.Errorf("absent-module call sites = %d nodes, want 0", len(got))
	}
	SetStructuralIndex(StructuralIndexAPI{ExternalSurface: fakeExternalSurface})
	if got := len(siAPI.ExternalCallSites(index)); got != 0 {
		t.Errorf("nil field default = %d, want 0", got)
	}

	installFakeIndex(t)
	wantCanon(t, "external_surface", idsOf(fakeExternalSurface(index)),
		validation.CanonCompact(objAt(oracle, "external_surface")))
	wantCanon(t, "external_call_sites", idsOf(fakeExternalCallSites(index)),
		validation.CanonCompact(objAt(oracle, "external_call_sites")))
	wantCanon(t, "external_surface_truthy",
		idsOf(fakeExternalSurface(objAt(doc, "index_truthy"))),
		validation.CanonCompact(objAt(oracle, "external_surface_truthy")))
	wantCanon(t, "external_call_sites_truthy",
		idsOf(fakeExternalCallSites(objAt(doc, "index_truthy"))),
		validation.CanonCompact(objAt(oracle, "external_call_sites_truthy")))
	wantCanon(t, "external_surface_empty",
		idsOf(fakeExternalSurface(objAt(doc, "empty_index"))),
		validation.CanonCompact(objAt(oracle, "external_surface_empty")))
	wantCanon(t, "external_call_sites_empty",
		idsOf(fakeExternalCallSites(objAt(doc, "empty_index"))),
		validation.CanonCompact(objAt(oracle, "external_call_sites_empty")))
}

// TestInitFromIndex replays every init_from_index oracle: the returned dict,
// the on-disk ledger bytes, and (with the seam absent) the feature-absent
// counters.
func TestInitFromIndex(t *testing.T) {
	t.Setenv("WEBV2_NOW", pinnedNow)
	doc := readTest(t, "oracle_init.json")
	installFakeIndex(t)
	for _, c := range casesOf(t, doc) {
		label := objStr(c, "label")
		index := parseCanon(t, label, objStr(c, "index"))
		model := parseCanon(t, label, objStr(c, "model"))
		want := objStr(c, "coverage")
		camp := newCamp(t, objStr(c, "campaign_id"))
		got, err := InitFromIndex(camp, index, model)
		if objAt(c, "error").Kind == validation.Obj {
			wantError(t, label, err, c)
			continue
		}
		if err != nil {
			t.Fatalf("%s: %v", label, err)
		}
		wantCanon(t, label, got, want)
		wantFile(t, label, Path(camp), objStr(c, "file"))
	}
}

// TestInitFromIndexSeamAbsent pins the documented feature-absent behavior:
// with no structural index module wired, the entry-point and external call
// site totals are 0 even though the index has them.
func TestInitFromIndexSeamAbsent(t *testing.T) {
	t.Setenv("WEBV2_NOW", pinnedNow)
	doc := readTest(t, "oracle_init.json")
	index := parseCanon(t, "index", objStr(casesOf(t, doc)[0], "index"))
	model := parseCanon(t, "model", objStr(casesOf(t, doc)[0], "model"))
	SetStructuralIndex(StructuralIndexAPI{})
	camp := newCamp(t, "C-covabsent01")
	cov, err := InitFromIndex(camp, index, model)
	if err != nil {
		t.Fatal(err)
	}
	surf := objAt(objAt(cov, "surfaces"), "external_call_sites")
	if got := objAt(surf, "total").I; got != 0 {
		t.Errorf("external_call_sites.total = %d, want 0", got)
	}
	row := objAt(cov, "contracts").A[0]
	if got := objAt(row, "entry_points_total").I; got != 0 {
		t.Errorf("entry_points_total = %d, want 0", got)
	}
	if got := objAt(row, "functions_total").I; got != 5 {
		t.Errorf("functions_total = %d, want 5 (index-only count)", got)
	}
}

// TestRecordSweep replays every record_sweep oracle.
func TestRecordSweep(t *testing.T) {
	t.Setenv("WEBV2_NOW", pinnedNow)
	doc := readTest(t, "oracle_sweeps.json")
	for _, c := range casesOf(t, doc) {
		label := objStr(c, "label")
		camp := seedCampaign(t, label, objStr(c, "seed"))
		got, err := RecordSweep(camp, objStr(c, "contract"), objStr(c, "trajectory"),
			SweepOpts{
				EntryPointsReviewed: objAt(c, "entry_points_reviewed").I,
				FunctionsReviewed:   objAt(c, "functions_reviewed").I,
				Complete:            objAt(c, "complete").B,
			})
		if objAt(c, "error").Kind == validation.Obj {
			wantError(t, label, err, c)
		} else {
			if err != nil {
				t.Fatalf("%s: %v", label, err)
			}
			wantCanon(t, label, got, objStr(c, "result"))
		}
		wantFile(t, label, Path(camp), objStr(c, "file"))
	}
}

// TestRecordSurface replays every record_surface oracle.
func TestRecordSurface(t *testing.T) {
	t.Setenv("WEBV2_NOW", pinnedNow)
	doc := readTest(t, "oracle_surfaces.json")
	for _, c := range casesOf(t, doc) {
		label := objStr(c, "label")
		camp := seedCampaign(t, label, objStr(c, "seed"))
		reviewed := objAt(c, "reviewed").I
		err := RecordSurface(camp, objStr(c, "surface"), reviewed)
		if objAt(c, "error").Kind == validation.Obj {
			wantError(t, label, err, c)
		} else if err != nil {
			t.Fatalf("%s: %v", label, err)
		} else {
			doc, err := Load(camp)
			if err != nil {
				t.Fatal(err)
			}
			seed := parseCanon(t, label, objStr(c, "seed"))
			total := objAt(objAt(objAt(seed, "surfaces"), objStr(c, "surface")), "total").I
			row := objAt(objAt(doc, "surfaces"), objStr(c, "surface"))
			if got := objAt(row, "reviewed").I; got != min(reviewed, total) {
				t.Errorf("%s: reviewed = %d, want min(%d, %d)", label, got, reviewed, total)
			}
		}
		wantFile(t, label, Path(camp), objStr(c, "file"))
	}
}

