// TestLoadSaveMisc pins load/save/path plus the two failure modes.
func TestLoadSaveMisc(t *testing.T) {
	t.Setenv("WEBV2_NOW", pinnedNow)
	misc := readTest(t, "oracle_misc.json")
	camp := seedCampaign(t, "misc", objStr(misc, "seed"))

	got, err := Load(camp)
	if err != nil {
		t.Fatal(err)
	}
	wantCanon(t, "load", got, objStr(misc, "load"))
	if want := filepath.Join(camp.ArtifactsDir, "coverage.json"); Path(camp) != want {
		t.Errorf("Path = %q, want %q", Path(camp), want)
	}
	path, err := Save(camp, &got)
	if err != nil {
		t.Fatal(err)
	}
	if path != Path(camp) {
		t.Errorf("Save path = %q, want %q", path, Path(camp))
	}
	wantFile(t, "saved_file", path, objStr(misc, "saved_file"))

	bad := parseCanon(t, "bad", objStr(misc, "bad"))
	camp2 := newCamp(t, "C-covmisc002")
	if _, err := Save(camp2, &bad); err == nil {
		t.Fatal("save_invalid: expected a SchemaError")
	} else if want := objStr(objAt(misc, "save_invalid"), "str"); err.Error() != want {
		t.Errorf("save_invalid = %q, want %q", err.Error(), want)
	}
	missing := newCamp(t, "C-covmisc003")
	if _, err := Load(missing); err == nil {
		t.Fatal("load_missing: expected an error")
	} else if !strings.Contains(err.Error(), "coverage.json") {
		t.Errorf("load_missing = %v; want the coverage.json path", err)
	}
}

// TestGoldenReplay is the parity probe: the scripted scenario from
// .scratch/t10/gen-vectors.py replayed on the Go side must reproduce the
// Python twin's coverage.json and events.jsonl byte for byte.
func TestGoldenReplay(t *testing.T) {
	g := readTest(t, "golden_replay.json")
	t.Setenv("WEBV2_NOW", objStr(g, "now"))
	installFakeIndex(t)

	camp := newCamp(t, objStr(g, "campaign_id"))
	sid := "SNAP-covt10"
	setActiveSnapshot(t, camp, validation.VStr(sid))
	snap := validation.VObj(
		kv("snapshot_id", validation.VStr(sid)),
		kv("deployment", objAt(g, "deployment")),
	)
	writeSnapshot(t, camp, sid, validation.CanonSpaced(snap))
	links := objAt(g, "links")
	if err := validation.WriteJson(
		filepath.Join(camp.ArtifactsDir, "invariant_links.json"), links, ""); err != nil {
		t.Fatal(err)
	}
	writeFindings(t, camp, objAt(g, "findings").A)

	index, model := objAt(g, "index"), objAt(g, "model")
	if _, err := InitFromIndex(camp, index, model); err != nil {
		t.Fatal(err)
	}
	sweeps := []struct {
		contract, trajectory string
		opts                 SweepOpts
	}{
		{"Vault", "code", SweepOpts{EntryPointsReviewed: 2, FunctionsReviewed: 1}},
		{"Vault.sol", "economic", SweepOpts{EntryPointsReviewed: 1, Complete: true}},
		{"src/Oracle.sol", "economic", SweepOpts{}},
	}
	for _, s := range sweeps {
		if _, err := RecordSweep(camp, s.contract, s.trajectory, s.opts); err != nil {
			t.Fatalf("record_sweep(%s): %v", s.contract, err)
		}
	}
	if err := RecordSurface(camp, "privilege_paths", 2); err != nil {
		t.Fatal(err)
	}
	if err := RecordSurface(camp, "external_call_sites", 1); err != nil {
		t.Fatal(err)
	}
	if _, err := RefreshGaps(camp, model); err != nil {
		t.Fatal(err)
	}
	if _, err := UpdateFunnel(camp); err != nil {
		t.Fatal(err)
	}
	thin, err := ThinCoverage(camp, 2)
	if err != nil {
		t.Fatal(err)
	}
	summary, err := BuildSummary(camp, index, model)
	if err != nil {
		t.Fatal(err)
	}

	wantCanon(t, "thin_coverage", validation.VArr(thin...), objStr(g, "thin_coverage"))
	wantCanon(t, "summary", summary, objStr(g, "summary"))
	wantFile(t, "coverage.json", Path(camp), objStr(g, "coverage_json"))
	wantFile(t, "events.jsonl", camp.EventsPath, objStr(g, "events_jsonl"))
	verdict, err := camp.VerifyLog()
	if err != nil {
		t.Fatal(err)
	}
	if !verdict.OK || verdict.Chained != 4 {
		t.Errorf("log verdict = %+v, want OK with 4 chained events", verdict)
	}
}

// TestPyNum pins the Python number semantics the ledger arithmetic relies on.
func TestPyNum(t *testing.T) {
	if got := numInt(2).add(numOf(validation.VFloat(0.5))).text(); got != "2.5" {
		t.Errorf("int + float = %s, want 2.5", got)
	}
	if got := numInt(3).min(numOf(validation.VFloat(4))).text(); got != "3" {
		t.Errorf("min(3, 4.0) = %s, want the int 3", got)
	}
	if got := numOf(validation.VFloat(1)).value(); validation.CanonCompact(got) != "1.0" {
		t.Errorf("float value = %s, want 1.0", validation.CanonCompact(got))
	}
	big := validation.VBigInt("123456789012345678901234567890")
	if got := numOf(big).addInt(1).text(); got != "123456789012345678901234567891" {
		t.Errorf("big + 1 = %s", got)
	}
	if got := numOrZero(validation.VNull()).text(); got != "0" {
		t.Errorf("or 0 = %s, want 0", got)
	}
	if got := numInt(1).div(validation.VInt(3)); validation.PythonFloat(
		validation.PythonRound(got, 3)) != "0.333" {
		t.Errorf("1/3 rounded = %v", got)
	}
	if got := numOrZero(validation.VInt(0)).addInt(5).text(); got != "5" {
		t.Errorf("0 or 0 + 5 = %s, want 5", got)
	}
}

// TestSetOrAppendAndTruthy pins the two dict primitives.
func TestSetOrAppendAndTruthy(t *testing.T) {
	kvs := []validation.KV{kv("a", validation.VInt(1)), kv("b", validation.VInt(2))}
	kvs = validation.SetOrAppend(kvs, "a", validation.VInt(9))
	if kvs[0].K != "a" || kvs[0].V.I != 9 || len(kvs) != 2 {
		t.Errorf("replace = %+v; want a=9 in place", kvs)
	}
	kvs = validation.SetOrAppend(kvs, "c", validation.VInt(3))
	if len(kvs) != 3 || kvs[2].K != "c" {
		t.Errorf("append = %+v; want c last", kvs)
	}
	for _, v := range []validation.Value{validation.VNull(), validation.VBool(false),
		validation.VInt(0), validation.VFloat(0), validation.VStr(""),
		validation.VArr(), validation.VObj()} {
		if pyTruthy(v) {
			t.Errorf("pyTruthy(%s) = true, want false", validation.CanonCompact(v))
		}
	}
	if !pyTruthy(validation.VStr("x")) || !pyTruthy(validation.VArr(validation.VInt(0))) {
		t.Error("pyTruthy of a non-empty value = false, want true")
	}
}
